class AetherSettingsView(context:Context):ScrollView(context){
 private val store=AetherSettingsStore(context);private var s=store.load();private val root=LinearLayout(context).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(20),dp(28),dp(20),dp(36));setBackgroundColor(0xFF080A0E.toInt())};private var page:String?=null
 init{setFillViewport(true);addView(root);render()}
 private fun render(){root.removeAllViews();if(page==null)home()else detail(page!!)}
 private fun home(){header("Aether Settings","Everything here persists on device.");panel("${s.homeMode.name.replace('_',' ')} • ${s.grid.columns}×${s.grid.rows}\nGlass ${s.glass.opacity}% • Dock ${s.dock.appCount}\nIsland ${on(s.island.enabled)} • Quick Space ${on(s.quickSpace.enabled)} • App Lock ${on(s.security.appLockEnabled)}");group("Personalize");card("Home","Launcher mode","home");card("Grid & Icons","Density, spacing, labels and folders","grid");card("Dock","Favorites count and appearance","dock");card("Glass & Appearance","Material, blur and theme","appearance");card("Motion","Springs and gestures","motion");group("Features");card("Dynamic Island","Live activity surface","island");card("Quick Space","Edge tools","quick");card("Control Center","System panel","control");card("Floating Windows","Window behavior","windows");card("Split Screen","Ratios and snapping","split");card("Security","App lock","security");group("System");card("Permissions & Access","Android permissions","permissions");card("Reset","Restore feature defaults","reset")}
 private fun detail(k:String){header(k.replaceFirstChar{it.uppercase()},"Aether settings");when(k){"home"->choice("Home mode",HomeMode.values().toList(),s.homeMode){s=s.copy(homeMode=it);save()};"grid"->{num("Columns",3,7,s.grid.columns){s=s.copy(grid=s.grid.copy(columns=it));save()};num("Rows",4,9,s.grid.rows){s=s.copy(grid=s.grid.copy(rows=it));save()};num("Icon size",40,72,s.grid.iconSize){s=s.copy(grid=s.grid.copy(iconSize=it));save()};toggle("Show labels",s.grid.showLabels){s=s.copy(grid=s.grid.copy(showLabels=it));save()};num("Label size",9,16,s.grid.labelSize){s=s.copy(grid=s.grid.copy(labelSize=it));save()};choice("Folder style",FolderStyle.values().toList(),s.grid.folderStyle){s=s.copy(grid=s.grid.copy(folderStyle=it));save()}};"dock"->{toggle("Dock enabled",s.dock.enabled){s=s.copy(dock=s.dock.copy(enabled=it));save()};num("Dock apps",3,8,s.dock.appCount){s=s.copy(dock=s.dock.copy(appCount=it));save()};num("Dock height",56,110,s.dock.height){s=s.copy(dock=s.dock.copy(height=it));save()};num("Dock radius",12,44,s.dock.radius){s=s.copy(dock=s.dock.copy(radius=it));save()};toggle("Smart groups",s.dock.smartGroups){s=s.copy(dock=s.dock.copy(smartGroups=it));save()}};"appearance"->{choice("Theme",AppearanceTheme.values().toList(),s.appearance.theme){s=s.copy(appearance=s.appearance.copy(theme=it));save()};num("Glass opacity",45,100,s.glass.opacity){s=s.copy(glass=s.glass.copy(opacity=it));save()};num("Blur",0,50,s.glass.blur){s=s.copy(glass=s.glass.copy(blur=it));save()};num("Saturation",80,135,s.glass.saturation){s=s.copy(glass=s.glass.copy(saturation=it));save()};num("Highlights",0,100,s.glass.highlight){s=s.copy(glass=s.glass.copy(highlight=it));save()};num("Corner radius",8,42,s.glass.cornerRadius){s=s.copy(glass=s.glass.copy(cornerRadius=it));save()};num("Wallpaper dim",0,40,s.appearance.wallpaperDim){s=s.copy(appearance=s.appearance.copy(wallpaperDim=it));save()}};"motion"->{choice("Preset",MotionPreset.values().toList(),s.motion.preset){s=s.copy(motion=s.motion.copy(preset=it));save()};num("Speed",50,160,s.motion.speed){s=s.copy(motion=s.motion.copy(speed=it));save()};num("Spring strength",150,800,s.motion.springStrength){s=s.copy(motion=s.motion.copy(springStrength=it));save()};num("Damping",10,80,s.motion.damping){s=s.copy(motion=s.motion.copy(damping=it));save()};num("Gesture sensitivity",10,100,s.motion.gestureSensitivity){s=s.copy(motion=s.motion.copy(gestureSensitivity=it));save()}};"island"->{toggle("Enabled",s.island.enabled){s=s.copy(island=s.island.copy(enabled=it));save()};toggle("Cutout aware",s.island.cutoutAware){s=s.copy(island=s.island.copy(cutoutAware=it));save()};num("Width",72,180,s.island.width){s=s.copy(island=s.island.copy(width=it));save()};num("Height",24,70,s.island.height){s=s.copy(island=s.island.copy(height=it));save()};toggle("Notifications",s.island.showNotifications){s=s.copy(island=s.island.copy(showNotifications=it));save()};toggle("Media",s.island.showMedia){s=s.copy(island=s.island.copy(showMedia=it));save()}};"quick"->{toggle("Enabled",s.quickSpace.enabled){s=s.copy(quickSpace=s.quickSpace.copy(enabled=it));save()};choice("Edge",QuickEdge.values().toList(),s.quickSpace.edge){s=s.copy(quickSpace=s.quickSpace.copy(edge=it));save()};num("Trigger distance",40,180,s.quickSpace.triggerDistance){s=s.copy(quickSpace=s.quickSpace.copy(triggerDistance=it));save()};toggle("Notes",s.quickSpace.notes){s=s.copy(quickSpace=s.quickSpace.copy(notes=it));save()};toggle("Recorder",s.quickSpace.recorder){s=s.copy(quickSpace=s.quickSpace.copy(recorder=it));save()};toggle("Calculator",s.quickSpace.calculator){s=s.copy(quickSpace=s.quickSpace.copy(calculator=it));save()};toggle("Screenshot",s.quickSpace.screenshot){s=s.copy(quickSpace=s.quickSpace.copy(screenshot=it));save()}};"control"->{toggle("Enabled",s.controlCenter.enabled){s=s.copy(controlCenter=s.controlCenter.copy(enabled=it));save()};num("Tile columns",1,4,s.controlCenter.columns){s=s.copy(controlCenter=s.controlCenter.copy(columns=it));save()};toggle("Brightness",s.controlCenter.showBrightness){s=s.copy(controlCenter=s.controlCenter.copy(showBrightness=it));save()};toggle("Volume",s.controlCenter.showVolume){s=s.copy(controlCenter=s.controlCenter.copy(showVolume=it));save()};toggle("Wi-Fi",s.controlCenter.showWifi){s=s.copy(controlCenter=s.controlCenter.copy(showWifi=it));save()};toggle("Bluetooth",s.controlCenter.showBluetooth){s=s.copy(controlCenter=s.controlCenter.copy(showBluetooth=it));save()};toggle("Airplane",s.controlCenter.showAirplane){s=s.copy(controlCenter=s.controlCenter.copy(showAirplane=it));save()};toggle("Rotation",s.controlCenter.showRotation){s=s.copy(controlCenter=s.controlCenter.copy(showRotation=it));save()};toggle("Flashlight",s.controlCenter.showFlashlight){s=s.copy(controlCenter=s.controlCenter.copy(showFlashlight=it));save()};toggle("DND",s.controlCenter.showDnd){s=s.copy(controlCenter=s.controlCenter.copy(showDnd=it));save()}};"windows"->{toggle("Enabled",s.floatingWindows.enabled){s=s.copy(floatingWindows=s.floatingWindows.copy(enabled=it));save()};num("Default width",50,95,s.floatingWindows.defaultWidth){s=s.copy(floatingWindows=s.floatingWindows.copy(defaultWidth=it));save()};num("Default height",40,90,s.floatingWindows.defaultHeight){s=s.copy(floatingWindows=s.floatingWindows.copy(defaultHeight=it));save()};num("Maximum windows",1,6,s.floatingWindows.maxWindows){s=s.copy(floatingWindows=s.floatingWindows.copy(maxWindows=it));save()};toggle("Resize edges",s.floatingWindows.edgeResize){s=s.copy(floatingWindows=s.floatingWindows.copy(edgeResize=it));save()};toggle("Resize corners",s.floatingWindows.cornerResize){s=s.copy(floatingWindows=s.floatingWindows.copy(cornerResize=it));save()};toggle("Snap windows",s.floatingWindows.snapWindows){s=s.copy(floatingWindows=s.floatingWindows.copy(snapWindows=it));save()}};"split"->{toggle("Enabled",s.splitScreen.enabled){s=s.copy(splitScreen=s.splitScreen.copy(enabled=it));save()};num("Default ratio",30,70,s.splitScreen.defaultRatio){s=s.copy(splitScreen=s.splitScreen.copy(defaultRatio=it));save()};toggle("Custom ratio",s.splitScreen.allowCustomRatio){s=s.copy(splitScreen=s.splitScreen.copy(allowCustomRatio=it));save()};toggle("Remember layouts",s.splitScreen.rememberLayouts){s=s.copy(splitScreen=s.splitScreen.copy(rememberLayouts=it));save()}};"security"->{toggle("App Lock",s.security.appLockEnabled){s=s.copy(security=s.security.copy(appLockEnabled=it));save()};toggle("Relock on leave",s.security.relockOnLeave){s=s.copy(security=s.security.copy(relockOnLeave=it));save()};toggle("Relock on screen off",s.security.relockOnScreenOff){s=s.copy(security=s.security.copy(relockOnScreenOff=it));save()};num("Relock timeout",0,300,s.security.relockTimeoutSeconds){s=s.copy(security=s.security.copy(relockTimeoutSeconds=it));save()};toggle("Biometrics",s.security.useBiometrics){s=s.copy(security=s.security.copy(useBiometrics=it));save()};root.addView(TextView(context).apply{text="Protected apps";textSize=18f;setTextColor(Color.WHITE)});AetherRuntime.registry.launcher.apps().forEach{a->check(a.label,AetherRuntime.security.protectedApps().contains(a.packageName)){v->if(v)AetherRuntime.security.protect(a.packageName)else AetherRuntime.security.unprotect(a.packageName)}}};"permissions"->{action("Default launcher","Choose Aether as Home"){context.startActivity(Intent(Settings.ACTION_HOME_SETTINGS))};action("Overlay","Allow Edge Space and Island"){context.startActivity(Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:${context.packageName}")))};action("Notification access","Feed live notifications"){context.startActivity(Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"))};action("Accessibility","Foreground sensing and app lock"){context.startActivity(Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))};action("Write settings","Brightness, rotation and DND"){context.startActivity(Intent(Settings.ACTION_MANAGE_WRITE_SETTINGS,Uri.parse("package:${context.packageName}")))}};"reset"->{panel("Reset layout and feature preferences. History, notes and protected apps stay separate.");action("Reset Aether","Start setup again"){store.resetSetup();Toast.makeText(context,"Aether reset. Reopen the launcher.",Toast.LENGTH_LONG).show()}}}}
 private fun header(t:String,sub:String){val r=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};if(page!=null)r.addView(Button(context).apply{text="‹";setOnClickListener{page=null;render()}},LinearLayout.LayoutParams(dp(52),dp(52)));val q=LinearLayout(context).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(8),0,0,0)};q.addView(TextView(context).apply{text=t;textSize=30f;setTextColor(Color.WHITE);typeface=android.graphics.Typeface.DEFAULT_BOLD});q.addView(TextView(context).apply{text=sub;textSize=13f;setTextColor(0xBFFFFFFF.toInt())});r.addView(q,LinearLayout.LayoutParams(0,-2,1f));root.addView(r,LinearLayout.LayoutParams(-1,dp(82)))}
 private fun group(t:String){root.addView(TextView(context).apply{text=t;textSize=18f;setTextColor(Color.WHITE);typeface=android.graphics.Typeface.DEFAULT_BOLD},LinearLayout.LayoutParams(-1,dp(42)))}
 private fun card(t:String,b:String,k:String){root.addView(Button(context).apply{text="$t\n$b";gravity=Gravity.START or Gravity.CENTER_VERTICAL;setTextColor(Color.WHITE);textSize=14f;setPadding(dp(18),0,dp(18),0);setOnClickListener{page=k;render()}},LinearLayout.LayoutParams(-1,dp(70)).apply{bottomMargin=dp(8)})}
 private fun panel(t:String){root.addView(TextView(context).apply{text=t;textSize=13f;setTextColor(Color.WHITE);setPadding(dp(16),dp(16),dp(16),dp(16));setBackgroundColor(0x181F2933)},LinearLayout.LayoutParams(-1,dp(88)).apply{bottomMargin=dp(12)})}
 private fun toggle(label:String,v:Boolean,a:(Boolean)->Unit){val r=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};r.addView(TextView(context).apply{text=label;textSize=14f;setTextColor(Color.WHITE)},LinearLayout.LayoutParams(0,dp(54),1f));r.addView(Switch(context).apply{isChecked=v;setOnCheckedChangeListener{_,x->a(x)}},LinearLayout.LayoutParams(dp(64),dp(52)));root.addView(r)}
 private fun num(label:String,min:Int,max:Int,v:Int,a:(Int)->Unit){val r=LinearLayout(context).apply{orientation=LinearLayout.VERTICAL;setPadding(0,dp(6),0,dp(6))};val h=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};val out=TextView(context).apply{text=v.toString();textSize=12f;setTextColor(0xBFFFFFFF.toInt());gravity=Gravity.END};h.addView(TextView(context).apply{text=label;textSize=14f;setTextColor(Color.WHITE)},LinearLayout.LayoutParams(0,dp(28),1f));h.addView(out,LinearLayout.LayoutParams(dp(54),dp(28)));val bar=SeekBar(context).apply{this.max=max-min;progress=(v-min).coerceIn(0,this.max);setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(sb:SeekBar?,p:Int,fromUser:Boolean){val n=p+min;out.text=n.toString();if(fromUser)a(n)};override fun onStartTrackingTouch(sb:SeekBar?){ };override fun onStopTrackingTouch(sb:SeekBar?){ }})};r.addView(h);r.addView(bar);root.addView(r)}
 private fun check(label:String,v:Boolean,a:(Boolean)->Unit){toggle(label,v,a)}
 private fun <E:Enum<E>> choice(label:String,values:List<E>,selected:E,a:(E)->Unit){val r=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};r.addView(TextView(context).apply{text=label;textSize=14f;setTextColor(Color.WHITE)},LinearLayout.LayoutParams(0,dp(56),1f));val sp=Spinner(context);sp.adapter=ArrayAdapter(context,android.R.layout.simple_spinner_dropdown_item,values.map{it.name.replace('_',' ').lowercase().replaceFirstChar{c->c.uppercase()}});sp.setSelection(values.indexOf(selected));sp.onItemSelectedListener=object:AdapterView.OnItemSelectedListener{override fun onItemSelected(parent:AdapterView<*>?,view:android.view.View?,position:Int,id:Long){a(values[position])};override fun onNothingSelected(parent:AdapterView<*>?){}};r.addView(sp,LinearLayout.LayoutParams(dp(190),dp(56)));root.addView(r)}
 private fun action(t:String,b:String,a:()->Unit){root.addView(Button(context).apply{text="$t\n$b";gravity=Gravity.START or Gravity.CENTER_VERTICAL;setTextColor(Color.WHITE);setOnClickListener{runCatching{a()}.onFailure{Toast.makeText(context,"Unavailable on this device",Toast.LENGTH_SHORT).show()}}},LinearLayout.LayoutParams(-1,dp(72)).apply{bottomMargin=dp(8)})}
 private fun save(){store.save(s)};private fun on(v:Boolean)=if(v)"ON" else "OFF";private fun dp(v:Int)= (v*resources.displayMetrics.density).roundToInt()
}
